const fixture=JSON.parse(readFileSync(new URL('./fixtures/monetary-row-identity-before.json',import.meta.url))),baseline=JSON.parse(readFileSync(new URL('../research/source-audit-batch5-monetary-row-identity-baseline.json',import.meta.url)));
const recordsFor=findings=>structuredClone(fixture.records.filter(r=>findings.some(f=>f.records.some(ref=>ref.uid===r.uid))));
const reviewBytes=Buffer.from('Synthetic independent-review protocol fixture; no real source approval.');
const reviewEvidence=new Map([['fixture-only',reviewBytes]]),evidence={path:'fixture-only',sha256:hash(reviewBytes)};
function sourceValueHashes(raw){const out={},relevant=/(?:typedValue|quantityOrScale|conditions?|qualifier|amount|currency|unit|rate|value|price|purpose|scale|formula)/i;function walk(value,path=''){if(Array.isArray(value)){value.forEach((v,i)=>walk(v,`${path}/${i}`));return;}if(value&&typeof value==='object'){for(const [key,child]of Object.entries(value))walk(child,`${path}/${key.replace(/~/g,'~0').replace(/\//g,'~1')}`);return;}if(path&&relevant.test(path.split('/')[1]||''))out[path]=hash(value);}walk(raw);return out;}

test('actual three distinct UA armor rows sharing wrong foci are detected before any repair',()=>{
 const findings=fixture.knownFindings.filter(f=>f.kind==='duplicate-wrong-row-focus');
 assert.equal(findings.length,3);assert.equal(fixture.sourceInputs.find(i=>i.key==='ua').sha256,'8ec8fcb1c937f1e5fdc86af87029a8defd1a4e9ee27c44ef9d0d84eef7e4577a');
 const report=auditMonetaryRowIdentity(recordsFor(findings),{knownFindings:findings});
 assert.equal(report.validation.valid,false);assert.equal(report.duplicateCandidates.length,3);
 assert.ok(report.duplicateCandidates.every(c=>c.status==='confirmed-wrong-row-focus'));
 for(const c of report.duplicateCandidates){assert.ok(c.evidence.some(e=>e.space==='pdf-page-points'));assert.ok(c.evidence.some(e=>e.space==='rendered-page-pixels'));}
});

