test('changing or deleting a known bad recipe cannot silently waive the source finding',()=>{
 const finding=fixture.knownFindings.find(f=>f.kind==='duplicate-wrong-row-focus'),records=recordsFor([finding]);
 records[1].geometry.filter(g=>g.role==='row-focus').forEach(g=>{g.bounds[1]+=30;g.bounds[3]+=30;});
 const changed=auditMonetaryRowIdentity(records,{knownFindings:[finding]});assert.equal(changed.validation.valid,false);assert.equal(changed.knownFindings[0].status,'focus-changed-needs-source-review');
 const missing=auditMonetaryRowIdentity(records.slice(0,1),{knownFindings:[finding]});assert.equal(missing.validation.valid,false);assert.equal(missing.knownFindings[0].status,'record-identity-changed-needs-source-review');
});

test('distinct aliases and shared prose require exact independent dispositions, even with a declared row link',()=>{
 const finding=fixture.knownFindings.find(f=>f.kind==='duplicate-wrong-row-focus'),records=recordsFor([finding]);
 for(const r of records)r.identity.sourceRowIds=['declared-shared-row'];
 const before=auditMonetaryRowIdentity(records);assert.equal(before.duplicateCandidates[0].status,'candidate-requires-source-review');assert.equal(before.duplicateCandidates[0].declaredSharedSourceRowLink,true);
 const review={id:'synthetic-shared-passage-disposition',independent:true,disposition:'legitimate-shared-passage',evidence,records:before.records.map(r=>({uid:r.uid,rowIdentitySha256:r.rowIdentitySha256,focusGeometrySha256:r.focusGeometrySha256,focusPhysicalFingerprintVersion:r.focusPhysicalFingerprintVersion,focusPhysicalGeometrySha256:r.focusPhysicalGeometrySha256}))};
 assert.equal(auditMonetaryRowIdentity(records,{reviews:[{...review,independent:false}],reviewEvidence}).duplicateCandidates[0].status,'candidate-requires-source-review');
 assert.equal(auditMonetaryRowIdentity(records,{reviews:[review]}).duplicateCandidates[0].status,'candidate-requires-source-review');
 assert.equal(auditMonetaryRowIdentity(records,{reviews:[review],reviewEvidence}).duplicateCandidates[0].status,'legitimate-shared-passage');
 review.records[0].focusGeometrySha256='b'.repeat(64);assert.equal(auditMonetaryRowIdentity(records,{reviews:[review],reviewEvidence}).duplicateCandidates[0].status,'candidate-requires-source-review');
});

test('a marker repair disposition binds the annotation itself and cannot approve a later omission',()=>{
 const finding=fixture.knownFindings.find(f=>f.kind==='missing-source-marker'),records=recordsFor([finding]);records[0].annotations['/footnoteMarkers']=[finding.expectedMarker];
 const snapshot=auditMonetaryRowIdentity(records),r=snapshot.records[0],review={id:'synthetic-source-marker-repair',independent:true,disposition:'source-reviewed-repair',supersedes:finding.id,evidence,records:[{uid:r.uid,rowIdentitySha256:r.rowIdentitySha256,focusGeometrySha256:r.focusGeometrySha256,annotationSha256:r.annotationSha256}]};
 assert.equal(auditMonetaryRowIdentity(records,{knownFindings:[finding],reviews:[review],reviewEvidence}).validation.valid,true);
 records[0].annotations['/footnoteMarkers']=[];assert.equal(auditMonetaryRowIdentity(records,{knownFindings:[finding],reviews:[review],reviewEvidence}).validation.valid,false);
});

