test('ordered disjoint focus rectangles are all inventoried and ambiguous old plus new shapes fail',()=>{
 const f={contextCropId:'crop',coordinateSpace:'crop-local 150-dpi source-render pixels',focusRectsCropPixelsLTRB:[[1,2,10,12],[20,30,40,50]]};
 const {records}=collectMonetaryRowIdentityRecords(minimalDocuments(f));assert.equal(records.length,1);assert.equal(records[0].geometry.length,4);assert.deepEqual(records[0].geometry.filter(g=>g.space==='crop-local-pixels').map(g=>g.bounds),f.focusRectsCropPixelsLTRB);assert.deepEqual(records[0].geometry.filter(g=>g.space==='rendered-page-pixels').map(g=>g.bounds),[[11,22,20,32],[30,50,50,70]]);
 assert.throws(()=>collectMonetaryRowIdentityRecords(minimalDocuments({...f,focusBoundsCropPixelsLTRB:[1,2,10,12]})),/Ambiguous single and multiple/);
 assert.throws(()=>collectMonetaryRowIdentityRecords(minimalDocuments({...f,focusRectsCropPixelsLTRB:[]})),/Invalid multiple/);
 assert.throws(()=>collectMonetaryRowIdentityRecords(minimalDocuments({...f,focusRectsCropPixelsLTRB:[[1,2,10,12]]})),/Invalid multiple/);
 assert.throws(()=>collectMonetaryRowIdentityRecords(minimalDocuments({...f,focusRectsCropPixelsLTRB:[[1,2,10,12],[5,6,20,30]]})),/Overlapping monetary/);
 assert.throws(()=>collectMonetaryRowIdentityRecords(minimalDocuments({...f,focusRectsCropPixelsLTRB:[[1,2,10,12],[20,30,100,50]]})),/outside crop/);
});

