 const before=monetaryContextPhysicalCropFingerprint(evidence,'wand-main-full-page');assert.match(before,/^[a-f0-9]{64}$/);assert.equal(monetaryContextPhysicalCropFingerprint(evidence,'unknown-crop'),null);
