test('UA token review rejects pointer, token, semantic, source, and forged-contract changes',()=>{
 const negatives=[
  ['both old single markers',ua=>{ua.rowRecords[54].footnoteMarkers=['*','*'];ua.rowRecords[61].footnoteMarkers=['*','*'];}],
  ['only one fixed',ua=>{ua.rowRecords[61].footnoteMarkers=['*','*'];}],
  ['wrong token',ua=>{ua.rowRecords[54].footnoteMarkers=['***'];}],
  ['extra token',ua=>{ua.rowRecords[54].footnoteMarkers=['**','*'];}],
  ['source value changed',ua=>{ua.rowRecords[61].values.gpSaleValue.amount=9999;}],
  ['source PDF changed',ua=>{ua.rowRecords[54].evidence.sourcePdfSha256='f'.repeat(64);}],
 ] ;
 for(const [label,mutateRows]of negatives){const {report,finding}=uaDoubleStarReviewProbe({mutateRows});assert.notEqual(report.knownFindings.find(f=>f.id===finding.id).status,'explicit-source-reviewed-repair',label);assert.notEqual(report.reviewResults[0].status,'current-explicit-review',label);}
 const findingPointer=uid=>uid.endsWith('r038')?'/rowRecords/54/footnoteMarkers':'/rowRecords/61/footnoteMarkers',controls=[
  ['forged absolute-pointer hash',(_,review)=>{review.records[0].confirmedPointerSha256[findingPointer(review.records[0].uid)]='f'.repeat(64);}],
  ['missing current record hash',(_,review)=>{delete review.records[0].recordSha256;}],
  ['foreign UID',(_,review)=>{review.records[0].uid='ua-supplement-row:foreign-row';}],
  ['extra reviewed pointer',(_,review)=>{review.records[0].confirmedPointerSha256['/rowRecords/54/footnoteMarkers']='0'.repeat(64);}],
  ['forged normalization metadata',ua=>{ua.rowRecords[54].footnoteMarkerNormalizationV3.reason='generic duplicate collapse';}],
 ];
 for(const [label,mutate]of controls){const {report,finding}=uaDoubleStarReviewProbe({mutateRows:ua=>{if(mutate.length===1)mutate(ua);},mutateReview:(review,current)=>{if(mutate.length===2)mutate(current,review);}});assert.notEqual(report.knownFindings.find(f=>f.id===finding.id).status,'explicit-source-reviewed-repair',label);assert.notEqual(report.reviewResults[0].status,'current-explicit-review',label);}
 const {report,finding}=uaDoubleStarReviewProbe({mutateFinding:f=>{f.confirmedPointers[0].expectedValue=['***'];f.confirmedPointers[0].sourceCorrection=['***'];}});assert.notEqual(report.knownFindings.find(x=>x.id===finding.id).status,'explicit-source-reviewed-repair');
});

