function oneFrozenUaContextRow(recordId){
 recordId=String(recordId).split(':').at(-1);const bytes=gunzipSync(readFileSync(new URL('./fixtures/monetary-source-ua-583-before.json.gz',import.meta.url))),source=JSON.parse(bytes.toString('utf8')),row=source.rowRecords.find(r=>r.recordId===recordId),groupId=recordId.match(/^(ua-other-\d+)/)?.[1],group=source.groupReviews.find(g=>g.groupId===groupId),docs=minimalDocuments({contextCropId:'crop',focusBoundsCropPixelsLTRB:[1,2,10,12]});
 docs.get('ua').sha256=hash(bytes);docs.get('ua').data={...source,groupReviews:[group],rowRecords:[row]};return {docs,row,group,source};
}
function linkUaContext(record,{changeFocus=false,changeLegacyContext=false}={}){
 const e=record.contextEvidence,segment=e.legacyProjection.rowContext.segmentId,old=e.legacyProjection.sourceEvidenceIndex.find(entry=>entry.segmentId===segment),uid=record.id,renderSha=old?.pageImageSha256||'c'.repeat(64),renderDims=old?.pageDimensionsPx||[1000,1200],pdfSha=record.source.sourceSha256,targetId='target-'+uid;
 const sourceRender={sourceRenderId:'native-render-'+uid,sourceRenderSha256:renderSha,sourceRenderDimensionsPx:renderDims,renderDpi:180,coordinateSpace:'source-render pixels, top-left origin'};
 const crop={cropBoundsPdfPagePointsTopLeftLTRB:[1,1,100,100],cropBoundsPixelsLTRB:[1,1,101,101],cropDimensionsPx:[100,100],cropSha256:'b'.repeat(64),renderDpi:180,coordinateSpace:'source-render pixels, top-left origin, LTRB half-open'};
 e.status='declared-active-context-targets-linked';e.activeTargetStatus='declared-active-context-targets-linked';e.declaredLinks=[{targetId,targetOrder:1,role:'table-context',segmentId:segment}];e.crops=[{cropId:targetId,targetOrder:1,role:'table-context',segmentId:segment,source:{book:'UA',sourcePdfSha256:pdfSha,printedPage:record.source.printedPage,pdfPage:record.source.pdfPage},sourceRender,metadata:{sourcePdfSha256:pdfSha,sourceRenderSha256:renderSha,sourceRenderDimensionsPx:renderDims,cropBoundsPdfPagePointsTopLeft:crop.cropBoundsPdfPagePointsTopLeftLTRB,cropBoundsPixelsLTRB:crop.cropBoundsPixelsLTRB,cropDimensionsPx:crop.cropDimensionsPx,cropSha256:crop.cropSha256,renderDpi:180,coordinateSpace:crop.coordinateSpace,sourceCrop:crop,pixelReview:{status:'independent-pixel-review-recorded'}}}];
 if(changeLegacyContext){const g=record.geometry.find(g=>g.role==='context-crop');g.bounds[2]+=2;}
 if(changeFocus){const g=record.geometry.find(g=>g.role==='row-focus');g.bounds[2]+=2;}
 record.contextEvidenceSha256=monetaryContextEvidenceFingerprint(e);return record;
}

